-- Open-flow board test (Basys2-250): the Block Memory wizard's module written as inferable HDL (#794, bram.vhd,
-- generated by core/blockram.js from init.mem): a RAM of 512 words of 16 bits, WRITE_FIRST, which synthesis maps
-- to a RAMB16_S18. The words are read one after the other (all of them about every 5 s); BTN0 held writes the
-- switches (twice: high and low byte) into the word shown:
--   LD7-LD0  the word's high byte when BTN1 is held, else its low byte
library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity top is
  port (clk : in  std_logic;
        btn : in  std_logic_vector(1 downto 0);
        sw  : in  std_logic_vector(7 downto 0);
        led : out std_logic_vector(7 downto 0));
end top;

architecture rtl of top is
  signal n : unsigned(23 downto 0) := (others => '0');
  signal word, din : std_logic_vector(15 downto 0);
  signal addr : std_logic_vector(8 downto 0);
begin
  process (clk) begin if rising_edge(clk) then n <= n + 1; end if; end process;
  addr <= std_logic_vector(n(23 downto 15));
  din <= sw & sw;
  u_ram : entity work.bram port map (clka => clk, wea => btn(0), addra => addr, dina => din, douta => word);
  led <= word(15 downto 8) when btn(1) = '1' else word(7 downto 0);
end rtl;
